<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<!-- <div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('User/index')}" class="on">用户列表</a>					<a href="{pigcms{:U('User/label_index')}">用户标签管理</a>					<a href="{pigcms{:U('User/privileged_user')}">特权用户</a>				</ul>			</div> -->			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('User/distributor')}" method="get">							<input type="hidden" name="c" value="User"/>							<input type="hidden" name="a" value="distributor"/>							筛选: 							<font color="#000">所属地区：</font>							<select name="project_city_id">								<option value="0">全部城市</option>								<volist name="project_city_arr" id="vo">									<option value="{pigcms{$vo['id']}" <if condition="$_GET['project_city_id'] eq $vo['id']">selected</if>>{pigcms{$vo['project_city_name']}</option>								</volist>							</select>							<font color="#000">所属项目：</font>							<select name="project_id">								<option value="0">全部项目</option>								<volist name="project_arr" id="vo">									<option value="{pigcms{$vo['id']}" <if condition="$_GET['project_id'] eq $vo['id']">selected</if>>{pigcms{$vo['project_name']}</option>								</volist>							</select>							<input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="pigcms_id" <if condition="$_GET['searchtype'] eq 'pigcms_id'">selected="selected"</if>>ID</option>								<option value="name" <if condition="$_GET['searchtype'] eq 'name'">selected="selected"</if>>姓名</option>								<option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>手机号</option>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							<font color="#000">日期筛选：</font>							<input type="text" class="input-text" name="begin_time" style="width:120px;" id="d4311"  value="{pigcms{$_GET.begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>			   							<input type="text" class="input-text" name="end_time" style="width:120px;" id="d4311" value="{pigcms{$_GET.end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>													状态:							<select name="status">								<option value="" <if condition="$_GET['status'] eq ' '">selected="selected"</if>>全部</option>								<option value="1" <if condition="$_GET['status'] eq '1'">selected="selected"</if>>正常</option>								<option value="0" <if condition="$_GET['status'] eq '0'">selected="selected"</if>>待审核</option>								<option value="2" <if condition="$_GET['status'] eq '2'">selected="selected"</if>>审核未通过</option>							</select>							<input type="submit" style="margin-right:20px;" value="查询" class="button"/>							<a href="javascript:void(0)" onclick="exports()" class="button" style="float:right;margin-right: 10px;">导出佣金记录</a>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<thead>							<tr>								<th>ID</th>								<th>姓名</th>								<th>用户昵称</th>								<th>手机号</th>								<th>所在城市</th>								<th>项目</th>								<th>佣金总额</th>								<th>状态</th>								<th>添加时间</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.pigcms_id}</td>										<td>{pigcms{$vo.name}</td>										<td>{pigcms{$vo.nickname}</td>										<td>{pigcms{$vo.phone}</td>										<td>{pigcms{$vo.city_name|default='<font color="#bbb">未知</font>'}</td>										<td>{pigcms{$vo.project_name}</td>										<td class="textcenter">{pigcms{$config['Currency_symbol']}{pigcms{$vo.money|floatval=###}<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('User/distributor_spread_list',array('uid'=>$vo['uid']))}','查看详情','75%',700,true,false,false,false,'detail',true);">查看详情</td>										<td class="textcenter"><if condition="$vo['status'] eq 1"><font color="green">正常</font><elseif condition="$vo['status'] eq 2" /><font color="red">审核不通过</font><else /><font color="red">待审核</font></if></td>										<td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>										<td class="textcenter">											<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('User/distributor_edit',array('pigcms_id'=>$vo['pigcms_id']))}','编辑信息',750,650,true,false,false,editbtn,'distributor_edit',true);"><if condition="$vo['status'] neq 1">审核<else />编辑</if>											</a>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script>		var url = "{pigcms{$config.site_url}"		var export_url = "{pigcms{:U('User/distributor_spread_export')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><script type="text/javascript">	$("select[name=project_city_id]").change(function () {		var project_city_id = $(this).val();		var city_name = $(this).find('option:selected').html();	    $.post('{pigcms{:U("ajax_get_project")}',{city_name:city_name},function (data) {	       	var html = '<option value="0">全部项目</option>';	       	if (data.length>0) {	       		for (var i = 0; i < data.length; i++) {	       			html += '<option value="'+data[i].id+'">'+data[i].project_name+'</option>';	       		}	       	}	       	$("select[name=project_id]").html(html);	    },'json')	})	</script><include file="Public:footer"/>